//! Compatibility tests against fixtures generated by the Go implementation.

use pm_mgr::{State, StateUpdate};
use pm_netenv::{CaptivePortal, OnlineStatus};
use pm_status::{SystemStatusRecord, WorstState};
use serde_json::{json, Value};

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/status.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn state_a() -> State {
    State {
        id: "module-a:error-1".to_string(),
        name: "Module A Error".to_string(),
        message: "Something went wrong.".to_string(),
        type_: pm_mgr::STATE_TYPE_ERROR.to_string(),
        time: 1_700_000_000,
        data: json!({"code": 42}),
    }
}

fn state_b() -> State {
    State {
        id: "module-b:hint-1".to_string(),
        name: "Module B Hint".to_string(),
        message: "Just so you know.".to_string(),
        type_: pm_mgr::STATE_TYPE_HINT.to_string(),
        time: 1_700_000_100,
        data: Value::Null,
    }
}

#[test]
fn state_update_matches_go() {
    let fixture = fixture();
    let expected = fixture["state_update"].as_str().unwrap();

    let update = StateUpdate::new("module-a", vec![state_a()]);
    let serialized = String::from_utf8(pm_dsd::gojson::to_vec(&update).unwrap()).unwrap();
    assert_eq!(serialized, expected);

    // The time is parsed back from RFC3339.
    let decoded: StateUpdate = serde_json::from_str(expected).unwrap();
    assert_eq!(decoded.states[0].time, 1_700_000_000);
    assert_eq!(decoded, update);
}

#[test]
fn system_status_matches_go() {
    let fixture = fixture();
    let expected = fixture["system_status"].as_str().unwrap();

    let status = SystemStatusRecord {
        online_status: OnlineStatus::SemiOnline,
        captive_portal: Some(CaptivePortal::new(
            "http://portal.example.com/login",
            "portal.example.com",
            Some("192.0.2.10".parse().unwrap()),
        )),
        modules: vec![
            StateUpdate::new("module-b", vec![state_b()]),
            StateUpdate::new("module-a", vec![state_a()]),
        ],
        // Go embeds the state, so the JSON of the worst state is flattened.
        worst_state: WorstState {
            module: "module-a".to_string(),
            state: state_a(),
        },
    };

    let serialized = String::from_utf8(pm_dsd::gojson::to_vec(&status).unwrap()).unwrap();
    assert_eq!(serialized, expected);

    let decoded: SystemStatusRecord = serde_json::from_str(expected).unwrap();
    assert_eq!(decoded.online_status, OnlineStatus::SemiOnline);
    assert_eq!(
        decoded.captive_portal.as_ref().unwrap().ip,
        Some("192.0.2.10".parse().unwrap())
    );
    assert_eq!(decoded.worst_state.module, "module-a");
    assert_eq!(decoded.worst_state.state.id, "module-a:error-1");
}

#[test]
fn online_status_names_match_go() {
    let fixture = fixture();
    for entry in fixture["online_statuses"].as_array().unwrap() {
        let value = entry["value"].as_u64().unwrap() as u8;
        let name = entry["name"].as_str().unwrap();
        assert_eq!(OnlineStatus::from_u8(value).as_str(), name, "{value}");
    }
}
